    var green = Color.floatToByte(this.green);
    var blue = Color.floatToByte(this.blue);
    var alpha = Color.floatToByte(this.alpha);

    if (!defined(result)) {
      return [red, green, blue, alpha];
    }
    result[0] = red;
    result[1] = green;
    result[2] = blue;
    result[3] = alpha;
    return result;
