    buttonsG.appendChild(this._playForwardSVG.svgElement);
    buttonsG.appendChild(this._pauseSVG.svgElement);

    var shuttleRingBackPanel = svgFromObject({
      tagName: "circle",
      class: "cesium-animation-shuttleRingBack",
      cx: 100,
      cy: 100,
      r: 99,
    });
